export type Status = 'new' | 'processing' | 'completed' | 'cancelled';
export type Order = {id: string; name: string; email: string; date: string; time: string; amount: number; status: Status; paid: boolean; product: string; items?: Order[]};
export const statuses: {id: Status; title: string}[] = [{id: 'new', title: 'Новые'}, {id: 'processing', title: 'В обработке'}, {id: 'completed', title: 'Выполнены'}, {id: 'cancelled', title: 'Отменены'}];
export const statusLabels: Record<Status, string> = {new: 'Новый', processing: 'В обработке', completed: 'Выполнен', cancelled: 'Отменён'};
const people = [['Анна Смирнова', 'anna.smirnova'], ['Михаил Иванов', 'm.ivanov'], ['Елена Козлова', 'elena.kozlova'], ['Дмитрий Соколов', 'd.sokolov'], ['Ольга Новикова', 'olga.novikova'], ['Александр Морозов', 'a.morozov'], ['Мария Волкова', 'm.volkova'], ['Иван Петров', 'ivan.petrov'], ['Анастасия Орлова', 'a.orlova'], ['Сергей Васильев', 's.vasiliev'], ['Виктория Белова', 'v.belova'], ['Артём Лебедев', 'a.lebedev']];
const cycle: Status[] = ['new', 'new', 'new', 'processing', 'processing', 'processing', 'processing', 'completed', 'completed', 'completed', 'cancelled', 'completed'];
export const initialOrders: Order[] = Array.from({length: 1284}, (_, i) => ({id: String(10482-i), name: people[i%12][0], email: "'`${people[i%12][1]}${i < 12 ? '"'' : i}@gmail.com"'`, date: `2026-11-0${4-Math.min(3, Math.floor(i/321))}`, time: `${String(14-Math.floor(i%12/3)).padStart(2,'"'0')}:"'${String((32-i%12*2)).padStart(2,'"'0')}"'`, amount: [12990, 8450, 24900, 5600, 18750, 32990, 4500, 15900, 7800, 21400, 9990, 6700][i%12], status: cycle[i%12], paid: i%5 !== 2, product: ['"'Наушники беспроводные', 'Рюкзак городской', 'Умная колонка', 'Настольная лампа'][i%4]}));
export const money = (n: number) => new Intl.NumberFormat('ru-RU').format(n) + ' ₽';
export function readSaved<T>(key: string, fallback: T): T {try {return JSON.parse(localStorage.getItem(key) || 'null') ?? fallback;} catch {return fallback;}}
export function save(key: string, value: unknown) {try {localStorage.setItem(key, JSON.stringify(value));} catch {/* Storage can be unavailable in private browsing. */}}
export function exportOrders(rows: Order[]) {const header = ['Заказ','Клиент','Email','Дата','Сумма','Статус','Оплата']; const escape = (v: unknown) => '\"' + String(v).replace(/\"/g, '\"\"') + '\"'; const csv = [header, ...rows.map(o => [o.id,o.name,o.email,o.date,o.amount,statusLabels[o.status],o.paid ? 'Оплачен' : 'Ожидает оплаты'])].map(row => row.map(escape).join(';')).join('\\r\\n'); const url = URL.createObjectURL(new Blob(['\\uFEFF'+csv], {type: 'text/csv;charset=utf-8;'})); const a = document.createElement('a'); a.href=url; a.download='orders.csv'; a.click(); URL.revokeObjectURL(url);}
